// client/src/components/RouletteWheel.jsx
import React, { useRef, useEffect, useState } from 'react';

function RouletteWheel({ rewards, rotationAngle }) {
  const [segments, setSegments] = useState([]);
  const radius = 200;
  const center = radius + 10;
  const degToRad = (d) => (d * Math.PI) / 180;

  useEffect(() => {
    if (Array.isArray(rewards) && rewards.length > 0) {
      setSegments(rewards.map((r) => ({ label: r.name, key: r.name, type: r.type })));
    }
  }, [rewards]);

  if (!segments || segments.length === 0) {
    return <div style={{ textAlign: 'center', padding: 32, color: '#888' }}>룰렛 로딩중...</div>;
  }

  return (
    <div style={{ position: 'relative', width: center * 2, height: center * 2 }}>
      {/* 화살표 */}
      <div style={{ 
        position: 'absolute', 
        left: '50%', 
        top: -15, 
        transform: 'translateX(-50%)', 
        width: 0, 
        height: 0, 
        borderLeft: '18px solid transparent', 
        borderRight: '18px solid transparent', 
        borderTop: '28px solid #ff5252', 
        zIndex: 50, 
        filter: 'drop-shadow(0 3px 6px rgba(255,82,82,0.4))' 
      }} />
      
      {/* SVG 룰렛 */}
      <svg 
        width={center * 2} 
        height={center * 2} 
        viewBox={`0 0 ${center * 2} ${center * 2}`}
        style={{ 
          display: 'block',
          transition: 'transform 4s cubic-bezier(.17,.67,.12,.99)',
          transform: `rotate(${rotationAngle}deg)`
        }}
      >
        <g transform={`translate(${center},${center})`}>
          {segments.map((seg, i) => {
            const angle = 360 / segments.length;
            const start = i * angle;
            const end = start + angle;
            const x1 = radius * Math.cos(degToRad(start));
            const y1 = radius * Math.sin(degToRad(start));
            const x2 = radius * Math.cos(degToRad(end));
            const y2 = radius * Math.sin(degToRad(end));
            const path = `M 0 0 L ${x1} ${y1} A ${radius} ${radius} 0 0 1 ${x2} ${y2} Z`;
            const textAngle = start + angle / 2;
            const textR = radius * 0.65;
            const textX = textR * Math.cos(degToRad(textAngle));
            const textY = textR * Math.sin(degToRad(textAngle));
            
            let color = '#ffd47a';
            if (seg.type === 'POINTS') color = '#9ee0ff';
            else if (seg.type === 'NONE') color = '#e0e0e0';

            return (
              <g key={i}>
                <path d={path} fill={color} stroke="#fff" strokeWidth={2} />
                <text 
                  x={textX} 
                  y={textY} 
                  fill="#333" 
                  fontSize={10} 
                  fontWeight={700} 
                  textAnchor="middle" 
                  dominantBaseline="middle"
                  transform={`rotate(${textAngle} ${textX} ${textY})`}
                >
                  {seg.label}
                </text>
              </g>
            );
          })}
        </g>
        {/* 중앙 원 */}
        <circle cx={center} cy={center} r={30} fill="#fff" stroke="#ff4d88" strokeWidth={3} />
        <text x={center} y={center + 4} textAnchor="middle" fontSize={12} fontWeight={800} fill="#ff4d88">SPIN</text>
      </svg>
    </div>
  );
}

export default RouletteWheel;
